        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_family_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_groups")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
