/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntityIngestionError {
    /// Errors related to the parliament API
    #[error("error when retrieving data from the parliament API: {0}")]
    ApiError(#[from] ParliamentApiError),

    /// Generic error related to entity parsing, cleaning and resolution
    #[error("error in ingestion pipeline: {0}")]
    DataError(String),

    /// Failure reading or writing ingestion storage.
    #[error("ingestion storage failed: {0}")]
    IoError(#[from] EntitySearchPipelineError),

    /// Invalid stage
    #[error("invalid stage provided: {0}")]
    InvalidStage(String),

    /// Invalid stage
    #[error("invalid ingestion ID: {0}")]
    UnvalidIngestionId(String),

    /// Generic error
    #[error("unexpected error occured: {0}")]
    UnexpectedError(String),
}
    }
}

fn data_error(message: impl Into<String>) -> EntityIngestionError {
    EntityIngestionError::DataError(message.into())
}
fn sql_timestamp(value: DateTime<Utc>) -> Result<time::OffsetDateTime, EntityIngestionError> {
    time::OffsetDateTime::from_unix_timestamp(value.timestamp())
        .and_then(|timestamp| timestamp.replace_nanosecond(value.timestamp_subsec_nanos()))
        .map_err(db_error)
}
fn read_error(error: impl std::fmt::Display) -> EntityIngestionError {
    EntityIngestionError::IoError(EntitySearchPipelineError::ReadError(error.to_string()))
}

#[cfg(test)]
mod tests;
fn db_error(error: impl std::fmt::Display) -> EntityIngestionError {
    EntityIngestionError::DataError(error.to_string())
}

